Lemma munch_acc0 : forall (W XS1 W2 : list (Z * Z)) m0 m m',
  munch (W ++ XS1) m0 m -> munch W2 m m' -> sub_fp W2 W -> munch (W ++ XS1) m0 m'.
Proof.
  intros W XS1 W2 m0 m m' A B SB. eapply munch_trans; [exact A|].
  eapply munch_weaken; [| exact B]. intros x. rewrite outside_app12. intros [K1 _]. exact (SB x K1).
Qed.

