(* [comment removed for export] *)
Ltac take_cells n cs := lazymatch n with O => constr:(@nil cell) | S ?n' => lazymatch cs with ?c :: ?cs' => let r := take_cells n' cs' in constr:(c :: r) end end.
Ltac drop_cells n cs := lazymatch n with O => cs | S ?n' => lazymatch cs with _ :: ?cs' => drop_cells n' cs' end end.
Ltac cut1 OBJ n NAME :=
  lazymatch type of OBJ with rw_cells ?sg ?mm ?a ?cs =>
    let pre := take_cells n cs in let post := drop_cells n cs in
    let sz := eval lazy in (Z.of_nat (cells_size pre)) in
    change (rw_cells sg mm a (pre ++ post)) in OBJ;
    apply (proj1 (rw_cells_app _ _ _ pre post)) in OBJ;
    let OBJ2 := fresh "OBQ" in
    destruct OBJ as [NAME OBJ2];
    lazymatch a with
    | ?b + ?k => let v := eval cbv in (k + sz)%Z in replace (a + Z.of_nat (cells_size pre)) with (b + v) in OBJ2 by (cbn [cells_size csize Nat.add length]; clear; lia)
    | _ => replace (a + Z.of_nat (cells_size pre)) with (a + sz) in OBJ2 by (cbn [cells_size csize Nat.add length]; clear; lia)
    end;
    rename OBJ2 into OBJ end.

Definition sc_final_cells (ioc : Z) (xs3 : word) (j50 jm8 j3 je jt j219 : list byte) (xa0 xa0' : word) : list cell :=
  [C8 (Z_to_bv 64 AVP_SCHED); CB 16 (poison_bytes 16 0); C8 (Z_to_bv 64 ioc); CB 16 (poison_bytes 16 0); C1 (b8 0); C1 (b8 0); CB 6 j50]
  ++ ([CB 8 jm8] ++ apmutex_cells 0 ++ [C4 (wz 0); CB 1 [b8 1]; CB 3 j3])
  ++ [CB 8 je]
  ++ (apcond_cells CLOCK_MONOTONIC ++ [C8 (wz 0)])
  ++ [C8 (Z_to_bv 64 0); C8 xs3; CB 20 (poison_bytes 20 0); CB 4 jt; C1 (b8 1); C1 (b8 0); C1 (b8 0); CB 5 j219; CB 24 (poison_bytes 24 0)]
  ++ [C8 xa0] ++ [C8 xa0'; C8 (Z_to_bv 64 0)].

Lemma asched_cells_fold : forall m S ioc (xs3 xa0 xa0' : word) j50 jm8 j3 je jt j219,
  rw_cells asegs m S (sc_final_cells ioc xs3 j50 jm8 j3 je jt j219 xa0 xa0') ->
  xs3 = wz P_A_SCHED_GET_DEFAULT_TASK -> xa0 = wz u64max -> xa0' = wz u64max -> 0 <= ioc < 2^64 -> S mod 16 = 0 ->
  ASchedCells m S ioc.
